// ══════════════════════════════════════════════
// ENTITY ART (r583) - pixel icons in place of the emoji on every entity tile
// ══════════════════════════════════════════════
// emGlyph (js/entity-tile.js) draws a glyph listed in PX_ICONS (js/data/icons.js,
// generated by tools/icons/build.js from game-icons.net) as a cell of the sprite
// sheet, with the emoji hidden inside it. Off, `html.px-emoji` shows the emoji
// again (css/px-icons.css); nothing re-renders.
// Dev -> HUD & Display -> Aesthetics -> Entity art. Store holds only 'off'.
const PX_ART_KEY = 'lethe.pxIcons.v1';
let pxIconsOn = (() => { try { return localStorage.getItem(PX_ART_KEY) !== 'off'; } catch (e) { return true; } })();

function pxIconsApply() {
  const h = document.documentElement;
  h.classList.toggle('px-emoji', !pxIconsOn);
  if (typeof PX_ICON_SHEET !== 'undefined') {
    h.style.setProperty('--px-sheet', `url("${new URL(PX_ICON_SHEET, location.href).href}")`);   // absolute: a url() in a custom property resolves against the stylesheet that reads it
    h.style.setProperty('--px-cell', (1 / (typeof PX_ICON_SIZE !== 'undefined' ? PX_ICON_SIZE : 32)) + 'em');   // one sheet pixel, for the light icons' outline
    // Fetch the sheet now, not on the first reward screen.
    if (pxIconsOn && !pxIconsApply._warm) { pxIconsApply._warm = new Image(); pxIconsApply._warm.src = PX_ICON_SHEET; }
  }
  const sel = document.getElementById('dev-px-icons'); if (sel) sel.value = pxIconsOn ? 'pixel' : 'emoji';
}

function setPxIcons(v) {
  pxIconsOn = !(v === 'emoji' || v === false);
  try { pxIconsOn ? localStorage.removeItem(PX_ART_KEY) : localStorage.setItem(PX_ART_KEY, 'off'); } catch (e) {}
  pxIconsApply();
}

pxIconsApply();
